-- LightPM schema - SQLite (local-first) edition.
--
-- This is the local mirror created automatically by lib/localDb.ts when the app
-- runs without Supabase credentials. It is kept here so the local shape is
-- readable and reviewable next to the Postgres one, and so you can open the
-- database with any SQLite tool.
--
-- Source of truth: supabase/schema.sql + supabase/migrations/*.sql
--   (see supabase/schema-manifest.json for the generated column list)
--
-- Differences from the Postgres schema, all deliberate:
--   * uuid      -> text   (ids are generated by the app, not the database)
--   * timestamptz/date -> text, stored as ISO-8601 strings
--   * boolean   -> integer 0/1
--   * text[]    -> text holding a JSON array (tasks.tags)
--   * no NOT NULL / UNIQUE / foreign keys and no triggers.
--     The application layer is the source of truth: it already generates ids,
--     stamps created_at/updated_at and performs cascade deletes itself. Adding
--     stricter constraints to the mirror could only reject writes the app
--     accepts, turning a working demo into a 500.
--
-- Consequence worth knowing: the database file will happily hold duplicate
-- project_members rows, because so does the app. That is pre-existing
-- behaviour, not something this layer introduced.
--
-- The database lives at data/lightpm.db (override with LIGHTPM_DB_PATH).

create table if not exists users (
  id text primary key,
  username text,
  password_hash text,
  name text,
  title text,
  role text,
  is_placeholder integer,
  created_at text
);

create table if not exists projects (
  id text primary key,
  name text,
  description text,
  status text,
  start_date text,
  end_date text,
  percent_complete integer,
  accent_color text,
  icon text,
  owner_id text,
  default_view text,
  archived_at text,
  created_by text,
  created_at text,
  updated_at text,
  reference_no text,
  type text,
  plan_class text,
  request_type text
);

create table if not exists project_statuses (
  id text primary key,
  project_id text,
  name text,
  key text,
  color text,
  sort_order integer,
  is_done integer
);

create table if not exists project_members (
  id text primary key,
  project_id text,
  user_id text,
  role text,
  added_at text
);

create table if not exists tasks (
  id text primary key,
  project_id text,
  parent_task_id text,
  title text,
  description text,
  status text,
  priority text,
  assignee_id text,
  start_date text,
  due_date text,
  duration_days integer,
  percent_complete integer,
  sort_order integer,
  tags text,
  reference_no text,
  created_by text,
  created_at text,
  updated_at text
);

create table if not exists task_comments (
  id text primary key,
  task_id text,
  user_id text,
  content text,
  created_at text
);

create table if not exists task_activity (
  id text primary key,
  task_id text,
  user_id text,
  action text,
  details text,
  created_at text
);

create index if not exists idx_tasks_project on tasks(project_id);
create index if not exists idx_tasks_assignee on tasks(assignee_id);
create index if not exists idx_tasks_status on tasks(status);
create index if not exists idx_task_comments_task on task_comments(task_id);
create index if not exists idx_task_activity_task on task_activity(task_id);
create index if not exists idx_project_statuses_project on project_statuses(project_id);
create index if not exists idx_project_members_project on project_members(project_id);

-- References out to Ticket / Change Request / Change Release. Those records live
-- in their own systems; title and progress_percent are typed by hand for the demo
-- and become values pulled by a direct query once those systems are reachable.
create table if not exists links (
  id text primary key,
  owner_kind text,
  owner_id text,
  kind text,
  reference text,
  title text,
  progress_percent integer,
  created_at text,
  updated_at text
);

-- People named on a project-less task; mirrors project_members.
create table if not exists task_members (
  id text primary key,
  task_id text,
  user_id text,
  role text,
  added_at text
);

create index if not exists idx_links_owner on links(owner_kind, owner_id);
create index if not exists idx_task_members_task on task_members(task_id);

-- Configurable lists: project type, plan class, request type.
create table if not exists config_options (
  id text primary key,
  list_key text,
  value text,
  label text,
  sort_order integer,
  created_at text
);

create index if not exists idx_config_options_list on config_options(list_key);

-- Handy queries while poking around:
--   select name, status, percent_complete from projects;
--   select status, count(*) from tasks group by status;
--   select username, name, role from users;
